cd /tmp && python3 - <<'EOF'
import math
from math import comb
def wilson(k,n,z=1.96):
    p=k/n; den=1+z*z/n
    c=(p+z*z/(2*n))/den
    h=z*math.sqrt(p*(1-p)/n+z*z/(4*n*n))/den
    return round(p,4), round(c-h,4), round(c+h,4)
for k in (150,141,134,16):
    print(k, wilson(k,164))
# exact McNemar for b=16,c=0 and b=10,c=1
def mc(b,c):
    n=b+c
    p=0
    for i in range(0,min(b,c)+1):
        p+=comb(n,i)
    return min(1, 2*p*0.5**n)
print('mcnemar 16vs0', mc(16,0))
print('mcnemar 10vs1', mc(10,1))
EOF

